static void ecm_notify_complete ( struct usb_ep * ep , struct usb_request * req ) { struct f_ecm * ecm = req -> context ; struct usb_composite_dev * cdev = ecm -> port . func . config -> cdev ; struct usb_cdc_notification * event = req -> buf ; switch ( req -> status ) { case 0 : break ; case - ECONNRESET : case - ESHUTDOWN : break ; default : DBG ( cdev , "event %02x -->%d\n" , event -> bNotificationType , req -> status ) ; break ; } ecm -> notify_req = req ; ecm_do_notify ( ecm ) ; } 